{"tool": "brick.build", "input": {"code": "script({
  title: "Imperial Star Destroyer - Devastator",
  description: "UCS-scale Imperial-class Star Destroyer with terraced command superstructure, dual deflector shield globes, tractor beam mast, 8 heavy turbolaser barbettes, lateral brim trench greebles, ventral hangar bay capturing the Tantive IV, triple primary ion engine cluster, and architectural display stand.",
  palette: {
    hull: "light bluish grey",
    trim: "dark bluish grey",
    stand: "black",
    ion: "trans light blue",
    red: "dark red",
    glow: "trans orange",
    sensor: "trans red"
  }
});

// 1. Modular Components for High-Density Surface Detailing
component("TrenchGreeble", {
  size: [1, 2],
  ops: [
    place({ part: "3023b", at: [0, 0, 0], colour: "trim", turn: 90 }),
    place({ part: "2412b", at: [0, 1, 0], colour: "trim", turn: 90 }),
    place({ part: "54200", at: [0, 2, 0], colour: "hull" }),
    place({ part: "6141", at: [0, 2, 1], colour: "sensor" }),
    place({ part: "4085c", at: [0, 3, 1], colour: "trim" }),
    place({ part: "4070", at: [0, 3, 0], colour: "hull" })
  ]
});

component("HullArmorPlate", {
  size: [2, 2],
  ops: [
    place({ part: "3022", at: [0, 0, 0], colour: "hull" }),
    place({ part: "3070b", at: [0, 1, 0], colour: "hull" }),
    place({ part: "54200", at: [1, 1, 0], colour: "hull" }),
    place({ part: "2412b", at: [0, 1, 1], colour: "trim" })
  ]
});

component("SuperstructureGreeble", {
  size: [2, 2],
  ops: [
    place({ part: "2877", at: [0, 0, 0], colour: "hull" }),
    place({ part: "3023b", at: [0, 3, 0], colour: "trim" }),
    place({ part: "2412b", at: [0, 4, 0], colour: "trim" }),
    place({ part: "54200", at: [0, 4, 1], colour: "hull" }),
    place({ part: "6141", at: [1, 4, 1], colour: "ion" })
  ]
});

component("TurbolaserBarbette", {
  size: [2, 2],
  ops: [
    place({ part: "4032b", at: [0, 0, 0], colour: "trim" }),
    place({ part: "3023b", at: [0, 1, 0], colour: "hull" }),
    place({ part: "3794b", at: [0, 1, 1], colour: "trim" }),
    place({ part: "4599b", at: [0, 2, 0], colour: "trim" }),
    place({ part: "4599b", at: [1, 2, 0], colour: "trim" }),
    place({ part: "54200", at: [0, 2, 1], colour: "hull" })
  ]
});

// Section 1: Museum Display Stand and Information Plaque
section("DisplayStand", [
  box({
    at: [-16, 0, -8],
    size: [32, 2, 26],
    colour: "stand",
    top: "tile"
  }),
  // Stand Perimeter Accent Border
  ...range(-16, 16).map(x => place({ part: "3070b", at: [x, 2, -8], colour: "trim" })),
  ...range(-16, 16).map(x => place({ part: "3070b", at: [x, 2, 17], colour: "trim" })),
  ...range(-7, 17).map(z => place({ part: "3070b", at: [-16, 2, z], colour: "trim" })),
  ...range(-7, 17).map(z => place({ part: "3070b", at: [15, 2, z], colour: "trim" })),
  // Heavy Forward and Aft Stanchions
  box({
    at: [-2, 2, -3],
    size: [4, 12, 3],
    colour: "stand",
    texture: "grille"
  }),
  box({
    at: [-2, 2, 13],
    size: [4, 12, 3],
    colour: "stand",
    texture: "grille"
  }),
  // Stanchion Keel Brackets
  place({ part: "3020", at: [-2, 14, -3], colour: "trim" }),
  place({ part: "3020", at: [-2, 14, 13], colour: "trim" }),
  // Presentation Plaque Base and Holo Emitters
  box({
    at: [-6, 2, -7],
    size: [12, 2, 2],
    colour: "trim",
    top: "tile"
  }),
  place({ part: "6141", at: [-5, 4, -7], colour: "ion" }),
  place({ part: "6141", at: [4, 4, -7], colour: "ion" })
]);

// Section 2: Ventral Keel, Reactor Core Bulb, and Hangar Bay with Tantive IV
section("VentralHull", [
  // Main Central Keel Box
  box({
    at: [-2, 14, -32],
    size: [4, 4, 62],
    colour: "hull"
  }),
  // Ventral Reactor Dome Bulb
  place({ part: "3960", at: [-2, 12, -10], colour: "hull" }),
  place({ part: "4032b", at: [-1, 11, -9], colour: "trim" }),
  // Ventral Hangar Bay Opening (Main Docking Cavern)
  box({
    at: [-3, 15, 2],
    size: [6, 3, 12],
    colour: "trim",
    texture: "grille"
  }),
  // Hangar Bay Guide Lights along ceiling
  ...range(3, 13).map(z => place({ part: "6141", at: [-2, 14, z], colour: "sensor" })),
  ...range(3, 13).map(z => place({ part: "6141", at: [1, 14, z], colour: "sensor" })),
  // Micro-scale Blockade Runner Tantive IV Captured in Tractor Beam
  place({ part: "3024", at: [0, 11, 4], colour: "white" }),
  place({ part: "54200", at: [0, 12, 4], colour: "red" }),
  place({ part: "3024", at: [0, 11, 5], colour: "hull" }),
  place({ part: "3023b", at: [-1, 11, 6], colour: "white" }),
  place({ part: "3070b", at: [-1, 12, 6], colour: "red" }),
  place({ part: "3070b", at: [0, 12, 6], colour: "red" }),
  place({ part: "3023b", at: [-1, 11, 7], colour: "white" }),
  place({ part: "6141", at: [-1, 11, 8], colour: "glow" }),
  place({ part: "6141", at: [0, 11, 8], colour: "glow" }),
  place({ part: "6141", at: [0, 13, 6], colour: "trans-clear" })
]);

// Section 3: Arrowhead Wedge Hull with Lateral Brim Trenches and Armor Paneling
section("MainHull", [
  ...range(-32, 30, 2).flatMap(z => {
    const w = Math.max(1, Math.min(20, Math.round(1 + (z + 32) * 19 / 62)));
    const ops = [];

    // Lower Hull Massing Core
    ops.push(box({
      at: [-w, 14, z],
      size: [2 * w + 1, 4, 2],
      colour: "hull"
    }));

    // Upper Hull Massing Core
    ops.push(box({
      at: [-(w - 1), 18, z],
      size: [2 * (w - 1) + 1, 4, 2],
      colour: "hull",
      top: "tile"
    }));

    // Lateral Brim Trench Greeble Modules (Port and Starboard)
    ops.push(instance({
      component: "TrenchGreeble",
      at: [-w, 16, z]
    }));
    ops.push(instance({
      component: "TrenchGreeble",
      at: [w, 16, z]
    }));

    // Leading Edge Outer Armor Slopes
    ops.push(place({
      part: "54200",
      at: [-w, 22, z],
      colour: "hull"
    }));
    ops.push(place({
      part: "54200",
      at: [w, 22, z],
      colour: "hull",
      turn: 180
    }));

    // Forward Dorsal Hull Plating (in front of the superstructure)
    if (z < 4 && w >= 3) {
      for (let x = -(w - 2); x <= (w - 4); x += 2) {
        ops.push(instance({
          component: "HullArmorPlate",
          at: [x, 22, z]
        }));
      }
    }

    // Ventral Hull Plating Modules (Aft and Mid-keel)
    if (w >= 4) {
      ops.push(instance({
        component: "HullArmorPlate",
        at: [-(w - 2), 13, z]
      }));
      ops.push(instance({
        component: "HullArmorPlate",
        at: [w - 3, 13, z]
      }));
    }

    return ops;
  })
]);

// Section 4: Terraced Superstructure and Turbolaser Batteries
section("Superstructure", [
  // Tier 1 Base Terraces (Z = 4 to 26)
  ...range(4, 26, 2).flatMap(z => {
    const tw = Math.round(6 + (z - 4) * 4 / 22);
    return [
      box({
        at: [-tw, 22, z],
        size: [2 * tw + 1, 4, 2],
        colour: "hull",
        texture: "masonry"
      }),
      place({ part: "2412b", at: [-tw, 26, z], colour: "trim", turn: 90 }),
      place({ part: "2412b", at: [tw, 26, z], colour: "trim", turn: 90 })
    ];
  }),

  // Surface Greebles on Tier 1 Deck
  ...range(6, 24, 4).flatMap(z => [
    instance({ component: "SuperstructureGreeble", at: [-5, 26, z] }),
    instance({ component: "SuperstructureGreeble", at: [3, 26, z] })
  ]),

  // 8 Heavy Turbolaser Barbettes (4 Port, 4 Starboard Flanking Batteries)
  ...[8, 13, 18, 23].flatMap(tz => {
    const tw = Math.round(6 + (tz - 4) * 4 / 22);
    return [
      instance({
        component: "TurbolaserBarbette",
        at: [-tw - 1, 26, tz]
      }),
      instance({
        component: "TurbolaserBarbette",
        at: [tw, 26, tz]
      })
    ];
  }),

  // Tier 2 Upper Command Deck
  box({
    at: [-5, 26, 12],
    size: [11, 4, 14],
    colour: "hull",
    texture: "grille",
    top: "tile"
  }),
  ...range(14, 24, 4).flatMap(z => [
    instance({ component: "SuperstructureGreeble", at: [-3, 30, z] }),
    instance({ component: "SuperstructureGreeble", at: [1, 30, z] })
  ]),

  // Tier 3 Cantilever Base
  box({
    at: [-3, 30, 18],
    size: [7, 3, 8],
    colour: "hull",
    top: "tile"
  }),

  // T-shaped Bridge Pylon Neck
  box({
    at: [-1, 33, 22],
    size: [3, 3, 3],
    colour: "trim"
  }),

  // Cantilevered Command Bridge Module
  box({
    at: [-7, 36, 22],
    size: [15, 3, 3],
    colour: "hull",
    top: "tile"
  }),
  // Command Bridge Visor Slit Viewports
  ...range(-6, 7).map(x => place({ part: "3070b", at: [x, 37, 21], colour: "trim" })),

  // Deflector Shield Generator Domes (Port and Starboard)
  place({ part: "4032b", at: [-6, 39, 22], colour: "trim" }),
  place({ part: "3941", at: [-6, 40, 22], colour: "hull" }),
  place({ part: "4740", at: [-6, 43, 22], colour: "hull" }),

  place({ part: "4032b", at: [4, 39, 22], colour: "trim" }),
  place({ part: "3941", at: [4, 40, 22], colour: "hull" }),
  place({ part: "4740", at: [4, 43, 22], colour: "hull" }),

  // Central Tractor Beam Targeting Vane and Communication Mast
  place({ part: "3957a", at: [0, 39, 22], colour: "trim" })
]);

// Section 5: Aft Transom and Massive Ion Thruster Cluster
section("EngineSection", [
  // Aft Transom Stern Wall
  box({
    at: [-20, 14, 30],
    size: [41, 12, 2],
    colour: "trim",
    texture: "grille",
    top: "tile"
  }),

  // Three Massive Primary Ion Engine Nacelles
  // Lower Port Primary Thruster
  cylinder({ at: [-10, 14, 32], diameter: 4, height: 9, colour: "hull" }),
  place({ part: "4032b", at: [-9, 15, 34], colour: "ion" }),
  place({ part: "4589", at: [-9, 15, 35], colour: "ion" }),
  place({ part: "2412b", at: [-10, 23, 32], colour: "trim" }),

  // Lower Starboard Primary Thruster
  cylinder({ at: [6, 14, 32], diameter: 4, height: 9, colour: "hull" }),
  place({ part: "4032b", at: [7, 15, 34], colour: "ion" }),
  place({ part: "4589", at: [7, 15, 35], colour: "ion" }),
  place({ part: "2412b", at: [6, 23, 32], colour: "trim" }),

  // Upper Center Primary Thruster
  cylinder({ at: [-2, 19, 32], diameter: 4, height: 9, colour: "hull" }),
  place({ part: "4032b", at: [-1, 20, 34], colour: "ion" }),
  place({ part: "4589", at: [-1, 20, 35], colour: "ion" }),
  place({ part: "2412b", at: [-2, 28, 32], colour: "trim" }),

  // Four Secondary Ion Thrusters in Aft Row
  ...[-15, -4, 3, 14].flatMap(x => [
    cylinder({ at: [x, 14, 32], diameter: 2, height: 6, colour: "trim" }),
    place({ part: "4032b", at: [x, 14, 34], colour: "ion" }),
    place({ part: "6141", at: [x, 14, 35], colour: "ion" })
  ])
]);
", "seed": 1}}

