// Section 3: Arrowhead Wedge Hull with Lateral Brim Trenches and Armor Paneling
section("MainHull", [
  ...range(-32, 30, 2).flatMap(z => {
    const w = Math.max(1, Math.min(20, Math.round(1 + (z + 32) * 19 / 62)));
    const ops = [];

    // Lower Hull Massing Core
    ops.push(box({
      at: [-w, 14, z],
      size: [2 * w + 1, 4, 2],
      colour: "hull"
    }));

    // Upper Hull Massing Core (steps in by 1 stud on each side)
    ops.push(box({
      at: [-(w - 1), 18, z],
      size: [2 * (w - 1) + 1, 4, 2],
      colour: "hull"
    }));

    // Lateral Brim Trench Greeble Modules (Port and Starboard at y = 18 on lower hull shelf)
    ops.push(instance({
      component: "TrenchGreeble",
      at: [-w, 18, z]
    }));
    ops.push(instance({
      component: "TrenchGreeble",
      at: [w, 18, z]
    }));

    // Leading Edge Outer Armor Slopes at y = 22
    if (w === 1) {
      ops.push(place({
        part: "54200",
        at: [0, 22, z],
        colour: "hull"
      }));
    } else {
      ops.push(place({
        part: "54200",
        at: [-(w - 1), 22, z],
        colour: "hull"
      }));
      ops.push(place({
        part: "54200",
        at: [w - 1, 22, z],
        colour: "hull",
        turn: 180
      }));
    }

    // Forward Dorsal Hull Plating (in front of superstructure, z < 4)
    if (z < 4 && w >= 3) {
      for (let x = -(w - 2); x <= (w - 4); x += 2) {
        ops.push(instance({
          component: "HullArmorPlate",
          at: [x, 22, z]
        }));
      }
    }

    // Flanking Dorsal Wing Plating (beside superstructure, z >= 4)
    if (z >= 4 && w >= 8) {
      const tw = Math.round(6 + (z - 4) * 4 / 22);
      for (let x = -(w - 2); x <= -tw - 3; x += 2) {
        ops.push(instance({
          component: "HullArmorPlate",
          at: [x, 22, z]
        }));
      }
      for (let x = tw + 2; x <= w - 3; x += 2) {
        ops.push(instance({
          component: "HullArmorPlate",
          at: [x, 22, z]
        }));
      }
    }

    // Ventral Hull Plating Modules (Underside facets)
    // Cleanly skips the forward stanchion, aft stanchion, reactor bulb, and hangar zones
    if (w >= 4) {
      for (let x = -(w - 2); x <= w - 4; x += 3) {
        const inHangar = (z >= 1 && z <= 15 && x >= -4 && x <= 3);
        const inBulb = (z >= -11 && z <= -6 && x >= -4 && x <= 3);
        const inFwdStanchion = (z >= -4 && z <= 0 && x >= -3 && x <= 2);
        const inAftStanchion = (z >= 12 && z <= 16 && x >= -3 && x <= 2);
        if (!inHangar && !inBulb && !inFwdStanchion && !inAftStanchion) {
          ops.push(instance({
            component: "HullArmorPlate",
            at: [x, 12, z]
          }));
        }
      }
    }

    return ops;
  })
]);

